import numpy as np

# Minimal Python micro-Autograd proving grad accumulation, detach, and in-place _version guard
class Var:
    def __init__(self, data, req=True):
        self.data = np.array(data, dtype=float); self.grad = None; self.req = req; self._ver = 0; self._bk = lambda: None
    def zero_grad(self): self.grad = None
    def detach(self): return Var(self.data, req=False)
    def add_inplace(self, c): self.data += c; self._ver += 1
    def square(self):
        saved_ver = self._ver; out = Var(self.data ** 2, req=self.req)
        def _bk():
            if self._ver != saved_ver: raise RuntimeError('In-place modification broke saved tensor!')
            if self.req: self.grad = (0.0 if self.grad is None else self.grad) + 2.0 * self.data * out.grad
        out._bk = _bk; return out
    def backward(self): self.grad = np.ones_like(self.data); self._bk()

w = Var(3.0)
w.square().backward(); w.square().backward()  # accumulates 6 + 6 = 12!
assert w.grad == 12.0
w.zero_grad(); y = w.detach().square(); y.backward(); assert w.grad is None  # detach stops grad
z = w.square(); w.add_inplace(1.0)  # mutates saved tensor
try:
    z.backward(); assert False
except RuntimeError as e:
    print(f'Accum grad=12.0, detach grad=None, in-place guard caught: {e}')
